def cert(i):
 return f'<button class="certificate cert-{i}" data-document="Сертификат — образец {i}" aria-label="Увеличить образец сертификата {i}"><span class="cert-brand">Өркендеу</span><small>УЧЕБНО-МЕТОДИЧЕСКИЙ ЦЕНТР</small><strong>СЕРТИФИКАТ</strong><span>о прохождении курса повышения квалификации</span><b>ОБРАЗЕЦ</b><small>Содержание документа будет заменено оригиналом</small></button>'
